const metadataLimit = "Only the identified publisher, author-institution or scholarly catalogue metadata and displayed description were checked. The original chapters, underlying cases and cited experiments were not reconstructed; bibliographic inclusion is not primary empirical support.";
function metadata(id, title, authors, year, url, doi = null, limit = "") {
  publication({ id, title, authors, year, url, doi, extent: "bibliographic-metadata-only", locators: ["Bibliographic metadata"], limit: [metadataLimit, limit].filter(Boolean).join(" ") });
}
