publication({ id: "eisenberger2003-social-exclusion", title: "Does Rejection Hurt? An fMRI Study of Social Exclusion", authors: ["Naomi I. Eisenberger", "Matthew D. Lieberman", "Kipling D. Williams"], year: 2003,
  doi: "10.1126/science.1091062", url: "https://www.uclascnlab.com/s/1_Cyberball290.pdf", journal: "Science", volume: "302", issue: "5643", pages: "290-292",
  extent: "main-article-and-figure-legends-supplementary-methods-unread", locators: ["Pages 290-292: Cyberball scan sequence, BOLD/distress results, Figures 1-2 and explicit design limitations"],
  limit: "The main article and figure legends were read in the authors' lab-hosted PDF, including its fixed-order warning. The separate supporting Methods, participant-level images, sample/exclusion details and analysis pipeline were not inspected. No physical-pain condition, chronic societal exposure, synaptic plasticity assay or selective brain-region perturbation was performed in this admitted preparation." });
study({ id: "eisenberger2003-cyberball-sequence", sourceId: "eisenberger2003-social-exclusion", system: "Human participants in the source virtual ball-tossing fMRI task",
  preparation: "Participants believe two computer-controlled players are real. Scans always proceed from watching because of a stated technical problem, to inclusion, to explicit exclusion after seven throws; explicit exclusion occurs only once. Measure BOLD and post-exclusion distress, with no distress report after the first scan.",
  observable: "Regional BOLD contrasts and correlations with reported social distress", finding: "Explicit exclusion versus inclusion shows ACC/RVPFC contrasts and different associations with distress; first-scan ACC activity also differs without a distress measurement for that scan.",
  limitations: ["Fixed scan order leaves period/expectation differences unresolved.", "BOLD correlation and statistical mediation do not identify one necessary neural pathway or prove identity of physical and social pain."] });
observation({ id: "social-exclusion-bold-association", name: "Ordered exclusion task and BOLD/distress associations", studyId: "eisenberger2003-cyberball-sequence", statement: "The paper reports larger ACC response during explicit exclusion than inclusion and a positive distress association; RVPFC response is negatively associated with distress. These are ordered-task imaging contrasts and correlations, with the source's stated control limitations." });
observation({ id: "social-exclusion-mechanism-boundary", name: "Statistical mediation differs from neural causal identification", studyId: "eisenberger2003-cyberball-sequence", statement: "The reported ACC mediation concerns statistical relations among imaging and distress measures. No selective ACC/RVPFC intervention, matched physical-pain task or chronic institutional manipulation identifies a unique social-to-neural causal mechanism." });

