card({ index: 20, name: "Societal Feedback on Individual Neurodynamics", slug: "social-neural-feedback-scope",
  scope: "The proposed societal-to-neural link is bounded here by acute ordered social-exclusion imaging and already admitted rat maternal-environment observations. Social context, reported distress, BOLD, chromatin profiles and long-term neural plasticity retain different populations, times and evidence types. No direct universal downward/diagonal causal law, chronic institutional control variable or minimum neural carrier is established.",
  bibliography: bibliography(["cacioppo2009-isolation-cognition", "eisenberger2012-social-health", "bourdieu1990-logic-practice"]),
  evidence: [finding("social-exclusion-bold-association"), finding("social-exclusion-mechanism-boundary"), inherited("neur:maternal-gr-developmental-association", "C-maternal-gr-developmental-association"), inherited("neur:maternal-chromatin-mediation", "C-maternal-chromatin-mediation")],
  assertions: [
    ["A social task can accompany a measurable neural readout", "qualified", "The source reports BOLD contrasts and distress associations under a specified exclusion sequence, retaining fixed order and missing supporting Methods.", ["C-soc-social-exclusion-bold-association"]],
    ["An acute exclusion episode proves persistent social embedding", "excluded", "The imaging task is a brief episode, whereas the original card specifically proposes persistent societal organization. The source does not measure enduring institutional exposure or posttask persistence.", ["C-soc-social-exclusion-bold-association"]],
    ["BOLD response, synaptic plasticity and stable neural regime are the same", "excluded", "No synaptic-plasticity assay, persistent dynamical-state identification or unique neuronal code is measured in this imaging preparation.", ["C-soc-social-exclusion-mechanism-boundary"]],
    ["ACC statistically mediating a relation proves a causal neural pathway", "excluded", "The mediation is correlational and no selective ACC/RVPFC perturbation was performed; the source's fixed scan order remains an alternative explanation component.", ["C-soc-social-exclusion-mechanism-boundary"]],
    ["Social and physical pain have an experimentally demonstrated identical mechanism", "unresolved", "The selected primary study contains no matched physical-pain condition or necessity test, so regional analogy does not identify one shared mechanism.", ["C-soc-social-exclusion-mechanism-boundary"]],
    ["Maternal-environment observations supply a human societal law", "excluded", "The existing rat source uses separate developmental cohorts and locus/assay-specific molecular observations. Those cannot be transferred to human institutions or the whole brain without matching evidence.", ["C-maternal-gr-developmental-association", "C-maternal-chromatin-mediation"]],
    ["Learning, valuation, stress, attention and decision thresholds all respond through one route", "unresolved", "Neither the imaging sequence nor the reused rat observations independently measure all proposed endpoints or identify one common mediator."],
    ["Institutions, norms, role obligations and reputation are separately isolated inputs", "unresolved", "These societal variables were not selectively manipulated by the admitted primary preparations."],
    ["The absence of genetic/pharmacological intervention isolates symbolic causation", "excluded", "An absence of those interventions does not exclude sensory, task-order, expectation or other physiological paths; the reused rat study's broader interventions also have their own scope.", ["C-soc-social-exclusion-mechanism-boundary", "C-maternal-chromatin-mediation"]],
    ["Downward and diagonal causal directions are measured by catalogue level labels", "excluded", "Levels organize topics; an identified exposure, endpoint, mediation test and cross-level variable are required before such directions become empirical relations."],
    ["Property-level assignment establishes a stable cross-level conditioning state", "qualified", "Property is an author-selected role for the research question, not an independently demonstrated persistent physiological state."]
  ], parents: [
    ["7.5", "unresolved", "Whole-society structure is not a separately operationalized intervention in the acute task or rat cohort study."],
    ["7.19", "qualified", "Perceived exclusion involves social interpretation, while national/group identity is not shown to be necessary for every recorded neural response.", ["C-soc-social-exclusion-bold-association"]],
    ["7.10", "unresolved", "No political/governance structure was manipulated as a causal or necessary neural input."],
    ["7.8", "unresolved", "The task has instructions and expectations, but a complete norm system is not isolated as the source of the BOLD contrast."],
    ["7.6", "unresolved", "A measured group intelligence capability is not present as a tested prerequisite of the neural response."],
    ["6.6", "qualified", "Reported distress and regional hemodynamic activity are relevant to affective processing; the broad affect category and its necessary causal route are not identified.", ["C-soc-social-exclusion-bold-association"]],
    ["6.11", "unresolved", "No specialized ensemble was selectively measured or perturbed to show its necessity for chronic social feedback."]
  ], unresolved: ["Define chronic social exposure and a repeated neural endpoint; separate fixed-order effects, distress reporting and selective neural mediation.", "Read the original imaging supporting Methods and reproduce analysis before quantitative neural use; rat maternal-care mechanisms retain their existing reporting and species limits."] });

card({ index: 21, name: "Sociogenesis of Shared Information Environments", slug: "shared-information-environments-scope",
  scope: "Shared information environments are represented as source-specific distributions of media salience, visible platform cues and fact-checked rumor exposure. The Chapel Hill media/public correlation, randomized platform response and observational diffusion are different preparations. A societal attractor, common credibility field, centralized-control independence or fixed sociogenetic construction order remains a hypothesis rather than a measured system state.",
  bibliography: bibliography(["luhmann1995-social-systems", "mccombs1972-agenda-setting", "castells2010-network-society"], { "mccombs1972-agenda-setting": "Selected original Method, Findings and Discussion were read. The study reports aggregate correlation and explicitly says it does not prove an agenda-setting function; it is primary observational evidence, not a randomized media effect." }),
  evidence: [finding("agenda-salience-association"), finding("voting-direct-response"), finding("rating-positive-herding"), finding("veracity-diffusion-association")],
  assertions: [
    ["Media emphasis and shared issue salience can be operationally compared", "supported", "The original study compares coded campaign coverage with important-issue reports in its restricted Chapel Hill sample.", ["C-soc-agenda-salience-association"]],
    ["Agenda correlations establish a directional media cause", "excluded", "The primary authors explicitly withhold causal proof. Exposure was not randomized and shared campaign causes or audience selection remain alternatives.", ["C-soc-agenda-salience-association"]],
    ["Shared information means complete consensus", "excluded", "Aggregate correspondence does not imply identical individual beliefs or perfect agreement across media, communities and topics.", ["C-soc-agenda-salience-association"]],
    ["Salience, credibility, factual truth and interpretation are one field", "excluded", "Issue emphasis, randomized approval and independently classified rumor veracity retain different operational definitions.", ["C-soc-agenda-salience-association", "C-soc-rating-positive-herding", "C-soc-veracity-diffusion-association"]],
    ["Information environments necessarily guide every collective action", "qualified", "The platform trial supplies a bounded behavioral response, including separate expression and turnout measures, without establishing universal necessity or every action channel.", ["C-soc-voting-direct-response", "C-soc-voting-information-turnout-null"]],
    ["Distributed attractor structure, inertia and tipping points are measured", "unresolved", "No state-space, return-after-perturbation assay, hysteresis protocol or threshold-identification test is present in the selected salience/diffusion records."],
    ["An information environment reproduces itself without centralized control", "unresolved", "Publisher metadata for Luhmann is not a causal test; media editors, platforms and experimental operators remain part of the measured systems."],
    ["Amplification and suppression have one stable mechanism across media", "unresolved", "Score seeding, campaign news selection and rumor diffusion do not isolate one shared suppression or amplification process.", ["C-soc-rating-positive-herding", "C-soc-veracity-diffusion-association"]],
    ["A social-scale pattern is established independently of measurement aggregation", "qualified", "Pattern is a declared description of related populations/exposures; aggregation units and sample boundaries determine what was actually compared.", ["C-soc-agenda-salience-association"]],
    ["The conceptual bibliography reconstructs the whole societal information system", "excluded", "Two metadata-only frameworks plus a restricted observational study do not constitute an exhaustive construction or validation of all societal information environments."]
  ], parents: [
    ["7.16", "unresolved", "The agenda study does not test an epistemic valuation regime as a necessary precursor; salience and evidential warrant differ.", ["C-soc-agenda-salience-association"]],
    ["7.15", "qualified", "Source selection and social cues can shape local exposure/response, without identifying a previously stabilized universal influence-network layer.", ["C-soc-voting-direct-response"]],
    ["7.18", "qualified", "Rumor propagation supplies a finite information-flow case, but a general memetic regime is not a tested necessary cause.", ["C-soc-veracity-diffusion-association"]],
    ["7.14", "qualified", "Digital infrastructure supports current platform cases, while the 1968 campaign preparation predates those platforms and supplies a separate media example.", ["C-soc-agenda-salience-association", "C-soc-voting-direct-response"]],
    ["7.8", "unresolved", "News/site conventions exist as context; no selective norm intervention establishes their universal maintenance necessity."]
  ], unresolved: ["Specify units, exposure distributions, salience measures, accuracy criteria and observation horizons before testing a persistent societal state or attractor."] });
// The primary agenda paper is actually reviewed; retain that distinction from its adjacent metadata-only frameworks.
CARD_SCOPES.find((record) => record.sourceIndex === 21).bibliography[1].disposition = "primary-evidence";

card({ index: 22, name: "Transculturation and Hybridization of Traditions", slug: "transculturation-scope",
  scope: "Transculturation is a declared historical-cultural research scope, illustrated by heterogeneous migrant-group profiles and bounded laboratory reorganization of transmitted labels. A mixed or intermediate measurement does not alone prove reciprocal historical transformation, creation of a novel tradition or irreducibility to cultural sources. Colonial power, unequal contact and adaptation claims require separately identified historical evidence.",
  bibliography: bibliography(["ortiz1940-counterpoint", "hannerz1996-transnational-connections", "appadurai1996-modernity-large"], { "ortiz1940-counterpoint": "The Duke publisher record is for the 1995 English reprint and explicitly identifies the 1940 original. The original Spanish text, translated chapters and historical sources remain unread; the title/year combination must not imply otherwise." }),
  evidence: [finding("migrant-measure-specific-profile"), finding("migrant-cognitive-group-nulls"), finding("language-filtered-structure")],
  assertions: [
    ["Contact between cultural populations can accompany differentiated profiles", "qualified", "The East London sample supplies measure-specific group associations, with distinct heritage/mainstream identification and observational transmission indicators.", ["C-soc-migrant-measure-specific-profile"]],
    ["Intermediate averages prove a newly stabilized hybrid tradition", "excluded", "An aggregate intermediate score is not a direct observation of a new practice, symbol, personal trajectory or historically persistent tradition.", ["C-soc-migrant-measure-specific-profile"]],
    ["Transformation is necessarily reciprocal rather than one-way", "unresolved", "The selected migrant design does not longitudinally measure both source and receiving populations; two-way historical transformation is not established."],
    ["Every cultural attribute converges or mixes under contact", "excluded", "Different measures have different profiles and selected cognitive tasks have no detected group difference.", ["C-soc-migrant-measure-specific-profile", "C-soc-migrant-cognitive-group-nulls"]],
    ["Transmission can reorganize symbolic structure", "qualified", "The filtered-language task demonstrates a finite reorganization of label/meaning structure, without reproducing cross-society historical contact or identity politics.", ["C-soc-language-filtered-structure"]],
    ["Symbols, narratives, identity and practices all share one hybridization mechanism", "unresolved", "The selected tasks and metadata-only books do not independently measure every proposed cultural component."],
    ["Hybridization guarantees adaptation to new conditions", "unresolved", "No common fitness, welfare or historical-success criterion was measured; structural mixture does not establish adaptiveness."],
    ["Hybridization reorganizes collective memory and historical identity", "unresolved", "The admitted questionnaires and label-transmission tasks do not track collective memory or long-term historical identity reconstruction."],
    ["Hybrid outcomes are ontologically irreducible to their sources", "excluded", "No reduction test, generative comparison or independently defined irreducibility criterion is supplied by these observations."],
    ["Colonial or geopolitical contacts are neutral symmetric exchanges", "excluded", "Reciprocity is a hypothesis, not an assumption that removes coercion or unequal power. The historical sources need case-specific reading before any such account is admitted."],
    ["Original and translated Ortiz editions are interchangeable evidence", "qualified", "The checked publisher catalogue identifies 1940 first publication and a 1995 English reprint. No historical passage reading is claimed for either edition."],
    ["A stable large-scale pattern follows from topic classification", "qualified", "Pattern is an organizing definition. Stability across generations, reciprocal pathways and cultural-source identity remain empirical tasks."]
  ], parents: [
    ["7.12", "qualified", "Cultural change supplies a conceptual comparison and finite task evidence, but no universal historical parent ordering is identified.", ["C-soc-language-filtered-structure"]],
    ["7.16", "unresolved", "No epistemic-market manipulation tests necessity for cross-cultural recombination."],
    ["7.21", "qualified", "Measured media/exposure indicators form part of the migrant comparison, without identifying one shared information environment as an obligatory mediator.", ["C-soc-migrant-measure-specific-profile"]],
    ["7.19", "qualified", "Affiliation measures vary across sampled groups, while identity is not selectively intervened upon to establish necessity for every hybrid form.", ["C-soc-migrant-measure-specific-profile"]],
    ["7.14", "unresolved", "Digital contact is not isolated as a needed condition of historical transculturation; metadata for Ortiz does not prove such a dependency."],
    ["7.11", "unresolved", "Institutional evolution and persistence were not measured as a required maintenance cause in the selected preparations."]
  ], unresolved: ["Read and compare the relevant historical primary materials; define a cultural variant, contact direction, coercion context and persistence horizon before claiming reciprocal hybrid tradition formation.", "Respect the 2018 migrant-table correction and measure-specific nulls; no group-essentialist or uniform assimilation inference follows."] });

card({ index: 23, name: "Mass Cognitive Distortion Regimes", slug: "collective-distortion-scope",
  scope: "The proposed mass-distortion regime remains a hypothesis bounded by fact-check-defined diffusion, randomized rating bias, a numerical-estimation feedback experiment and partisan attitude responses. A factual error, preference, ideological extremity, approval score, retweet and confidence judgment are distinct. No persistent societal attractor, common cognitive pathology or universal network-amplification mechanism is established.",
  bibliography: bibliography(["tversky1974-heuristics", "sunstein2002-group-polarization", "kahneman2011-thinking"]),
  evidence: [finding("veracity-diffusion-association"), finding("diffusion-belief-mechanism-boundary"), finding("rating-positive-herding"), finding("rating-negative-final-null"), finding("opposing-view-republican-shift"), finding("opposing-view-democratic-null"), inherited("soc:feedback-diversity-confidence", "C-soc-feedback-diversity-confidence")],
  assertions: [
    ["Distortion needs an independent accuracy criterion", "supported", "Fact-check labels and known numerical answers supply declared criteria in their respective preparations; popularity and partisan direction supply none.", ["C-soc-veracity-diffusion-association", "C-soc-feedback-diversity-confidence"]],
    ["Social signals can bias later approval", "supported", "Randomized initial scores change later website ratings, with positive/negative asymmetry and topic-specific nulls.", ["C-soc-rating-positive-herding", "C-soc-rating-negative-final-null"]],
    ["False information can propagate widely", "qualified", "The sampled fact-checked Twitter rumors show broader/faster false-classified diffusion, without a claim that all falsehood always spreads or that all sharers believe it.", ["C-soc-veracity-diffusion-association"]],
    ["Retweeting a false-classified claim directly measures false belief", "excluded", "Sharing, belief, deception intent and cognitive motive are not interchangeable measurements.", ["C-soc-diffusion-belief-mechanism-boundary"]],
    ["Policy polarization is itself a factual error", "excluded", "The opposing-view trial measures policy attitudes. No independent factual-truth criterion marks either partisan direction as false.", ["C-soc-opposing-view-republican-shift", "C-soc-opposing-view-democratic-null"]],
    ["Exposure to disagreement always corrects or always worsens judgment", "excluded", "The randomized policy study yields a cohort-specific conservative shift and a Democratic-cohort null; these do not establish either universal direction.", ["C-soc-opposing-view-republican-shift", "C-soc-opposing-view-democratic-null"]],
    ["Reduced diversity and higher confidence necessarily improve accuracy", "excluded", "The separate estimation-feedback evidence distinguishes convergence/confidence from corresponding accuracy improvement in its finite tasks.", ["C-soc-feedback-diversity-confidence"]],
    ["Novelty, affect, identity and topology form a uniquely identified mediator", "unresolved", "Reply lexicons, topic distance, partisan grouping and social exposure do not isolate one common mechanism across these preparations.", ["C-soc-diffusion-belief-mechanism-boundary", "C-soc-opposing-view-republican-shift"]],
    ["Observed biases establish a stable societal-scale regime", "unresolved", "The studies provide limited populations/windows and different endpoints, without a defined state-space, recovery protocol, hysteresis or invariant social pathology."],
    ["Mass miscalibration causes policy outcomes through the claimed channel", "unresolved", "No matched causal chain from the selected distortion measure to legislation, resource allocation or long-term policy outcome is reconstructed."],
    ["Individual heuristics directly prove collective distortion", "excluded", "The original synthesis/theory references are bibliographic and cannot bridge individuals to an entire population without explicit aggregation and exposure evidence."],
    ["The condition is irreducible to individual intent by definition", "unresolved", "A property label does not demonstrate causal irreducibility or exclude heterogeneous individual motives; system-level scope remains a testable proposal."]
  ], parents: [
    ["7.21", "qualified", "Declared information exposure supplies context, while no whole societal-environment regime is shown necessary for each finite bias effect.", ["C-soc-rating-positive-herding", "C-soc-veracity-diffusion-association"]],
    ["7.14", "qualified", "Digital platforms host several measured cases, but their necessity for every cognitive distortion or factual mistake is not tested.", ["C-soc-rating-positive-herding"]],
    ["7.19", "qualified", "Partisan identity defines the recruited cohorts, while no selective identity intervention identifies a required mediator of all distortion.", ["C-soc-opposing-view-republican-shift", "C-soc-opposing-view-democratic-null"]],
    ["7.18", "qualified", "Rumor propagation is measured separately from belief/error, so a memetic ontology is not a demonstrated enabling mechanism.", ["C-soc-diffusion-belief-mechanism-boundary"]],
    ["6.3", "unresolved", "No neural decision-site intervention or necessary accumulator architecture is measured in these social-information studies."]
  ], unresolved: ["Define factual calibration separately from policy preference and normative disagreement; preregister aggregation, persistence and contrary-outcome criteria before testing a mass regime.", "Independent primary-data and mechanism checks remain necessary; the included studies are heterogeneous cases rather than independent replications of one phenomenon."] });

